def _advance_fanout_cursor(self, channel_id: str, agent_id: str, message_id: str) -> None:
    message = self.db.get_message_by_id(message_id)
    if message is None:
        return
    seq = message["channel_seq"]
    sub = self.db.get_subscription(channel_id, agent_id)
    if sub is None:
        return
    current = sub["cursor_seq"]
    if seq <= current:
        return
    if seq == current + 1:
        self.db.advance_cursor(channel_id, agent_id, seq)
        target = seq
        while True:
            target += 1
            next_msg = self.db.execute(
                "SELECT m.message_id, m.channel_seq FROM messages m "
                "WHERE m.channel_id = ? AND m.channel_seq = ?",
                (channel_id, target),
            ).fetchone()
            if next_msg is None:
                break
            next_del = self.db.execute(
                "SELECT 1 FROM deliveries d WHERE d.message_id = ? "
                "AND d.agent_id = ? AND d.state IN ('acked','dead')",
                (next_msg["message_id"], agent_id),
            ).fetchone()
            if next_del is not None:
                self.db.advance_cursor(channel_id, agent_id, target)
            else:
                break
    else:
        all_acked = True
        for check_seq in range(current + 1, seq):
            check_msg = self.db.execute(
                "SELECT m.message_id FROM messages m WHERE m.channel_id = ? AND m.channel_seq = ?",
                (channel_id, check_seq),
            ).fetchone()
            if check_msg is None:
                continue
            check_del = self.db.execute(
                "SELECT 1 FROM deliveries d WHERE d.message_id = ? "
                "AND d.agent_id = ? AND d.state IN ('acked','dead')",
                (check_msg["message_id"], agent_id),
            ).fetchone()
            if check_del is None:
                all_acked = False
                break
        if all_acked:
            self.db.advance_cursor(channel_id, agent_id, seq)

